mapper.select:
SELECT * FROM kb_ai_call WHERE retention_anchor_at <= #{cutoff}
    AND generation_status <> 'RUNNING' AND settlement_status IN ('SETTLED','NOT_REQUIRED')
ORDER BY retention_anchor_at, id LIMIT #{limit} FOR UPDATE SKIP LOCKED

SELECT * FROM kb_ai_call WHERE mode = 'SINGLE' AND generation_status <> 'RUNNING'
    AND settlement_status = 'PENDING' AND finalized_at <= #{cutoff}
ORDER BY finalized_at, id LIMIT #{limit}

mapper.sql:
started_at >= #{from} AND started_at < #{to}
AND user_id = #{userId}
AND department_id = #{departmentId}
AND mode = #{mode}
AND generation_status = #{generationStatus}
AND usage_status = #{usageStatus}
AND settlement_status = #{settlementStatus}

mapper.select:
SELECT  AS "key", 
FROM kb_ai_call WHERE 
AND  > #{afterGroup}
GROUP BY  ORDER BY "key" LIMIT #{fetch}

SELECT *, payload::text AS payload FROM kb_ai_call_event
WHERE occurred_at >= #{from} AND occurred_at < #{to} AND id <= #{upper}
AND (occurred_at, id) < (#{lastTime}, #{lastId})
AND call_id = CAST(#{callId} AS uuid)
AND kind = #{eventType}
AND payload->>'userId' = CAST(#{userId} AS text)
AND payload->>'departmentId' = CAST(#{departmentId} AS text)
AND payload->>'mode' = #{mode}
AND payload->>'generationStatus' = #{generationStatus}
AND payload->>'usageStatus' = #{usageStatus}
AND payload->>'settlementStatus' = #{settlementStatus}
ORDER BY occurred_at DESC, id DESC LIMIT #{fetch}

SELECT opened_at AS "openedAt", closed_at AS "closedAt", retention_days AS "retentionDays"
FROM kb_ai_collection_period WHERE opened_at < #{to} AND (closed_at IS NULL OR closed_at > #{from})
ORDER BY opened_at LIMIT #{limit}
